Here’s a quick, non‑intrusive way to add a dark‑mode toggle **and** fix the mobile‑save button.  
I’ll only touch the files you asked for – `Settings.jsx` (and a tiny helper) – and leave the `Header` component untouched.

---

## 1️⃣ Add a Theme Context

Create a tiny context that will hold the current theme and a toggler.

```diff
// src/theme.js
+ import { createContext, useContext, useState, useEffect } from "react";

+ export const ThemeContext = createContext({
+   theme: "light",
+   toggleTheme: () => {},
+ });

+ export const ThemeProvider = ({ children }) => {
+   const [theme, setTheme] = useState("light");

+   const toggleTheme = () => {
+     setTheme((prev) => (prev === "light" ? "dark" : "light"));
+   };

+   // Persist choice in localStorage & add class to <html>
+   useEffect(() => {
+     localStorage.setItem("theme", theme);
+     document.documentElement.setAttribute("data-theme", theme);
+   }, [theme]);

+   return (
+     <ThemeContext.Provider value={{ theme, toggleTheme }}>
+       {children}
+     </ThemeContext.Provider>
+   );
+ };

+ export const useTheme = () => useContext(ThemeContext);
```

*Add the provider once (e.g., in `src/index.js` or `App.jsx`):*

```diff
// src/index.js
import ReactDOM from "react-dom";
import App from "./App";
+ import { ThemeProvider } from "./theme";

ReactDOM.render(
  <React.StrictMode>
+    <ThemeProvider>
      <App />
+    </ThemeProvider>
  </React.StrictMode>,
  document.getElementById("root")
);
```

