## 2️⃣ Update Settings.jsx

```diff
// src/Settings.jsx
import React, { useState } from "react";
import { useTheme } from "./theme";          // ← NEW
import "./Settings.css";  // make sure this exists

const Settings = () => {
  const { theme, toggleTheme } = useTheme();   // ← NEW
  const [formData, setFormData] = useState({
    // your existing form fields…
  });

  /* ----- existing form handlers ----- */

  const handleSave = async (e) => {
    e.preventDefault();
    try {
      /* existing save logic …*/
      alert("Settings saved!");
    } catch (err) {
      console.error(err);
      alert("Error saving settings");
    }
  };

  return (
    <div className="settings-container">
      <h2>Settings</h2>

      {/* ----- NEW DARK‑MODE TOGGLE ----- */}
      <div className="toggle-wrapper">
        <label htmlFor="dark-mode-toggle" className="toggle-label">
          Dark Mode
        </label>
        <button
          id="dark-mode-toggle"
          type="button"
          onClick={toggleTheme}
          className={`toggle-btn ${theme === "dark" ? "on" : "off"}`}
          aria-pressed={theme === "dark"}
          aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
        >
          {theme === "dark" ? "🌙" : "☀️"}
        </button>
      </div>

      {/* ----- YOUR EXISTING FORM ----- */}
      <form onSubmit={handleSave} className="settings-form">
        {/* ... your fields */}
        {/* ----- MOBILE‑SAVE BUTTON FIX ----- */}
        <button
          type="submit"
          className="save-btn"
          // Make sure it's in the DOM hierarchy the mobile menu expects
          style={{ marginTop: "1rem" }}
        >
          Save
        </button>
      </form>
    </div>
  );
};

export default Settings;
```

### What’s happening?

| Part | Why it matters |
|------|----------------|
| **ThemeContext** | Keeps the theme state global. |
| **`data-theme` attribute** | Easier CSS targeting (`[data-theme="dark"] { … }`). |
| **Toggle button** | Accessible (`aria-pressed`). Uses emoji icons for quick visual. |
| **Save button** | Explicit `type="submit"` and a `marginTop` ensure it’s not overlapped by the mobile bar. |

